-- 3. Latency of streamed changes (snapshot rows excluded), last hour:
--    Oracle commit -> Snowflake connector push.
SELECT
  COUNT(*)                                                            AS changes,
  APPROX_PERCENTILE((RECORD_METADATA:SnowflakeConnectorPushTime::NUMBER
                     - RECORD_CONTENT:source.ts_ms::NUMBER) / 1000, 0.5) AS p50_seconds,
  APPROX_PERCENTILE((RECORD_METADATA:SnowflakeConnectorPushTime::NUMBER
                     - RECORD_CONTENT:source.ts_ms::NUMBER) / 1000, 0.9) AS p90_seconds
FROM (
  SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.T001_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.T001W_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.TVKO_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.TVTW_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.TSPA_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.TVTA_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.TVAK_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.TVLK_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.TVFK_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.BUT000_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.CVI_CUST_LINK_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.KNA1_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.KNB1_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.KNVV_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.KNVP_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.MARA_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.MAKT_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.MARC_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.MVKE_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.PRCD_ELEMENTS_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.VBAK_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.VBAP_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.VBEP_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.VBKD_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.VBPA_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.VBFA_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.LIKP_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.LIPS_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.VBRK_RAW
  UNION ALL SELECT RECORD_CONTENT, RECORD_METADATA FROM SAP_RAW.SD.VBRP_RAW
)
WHERE RECORD_CONTENT:op::STRING IN ('c', 'u', 'd')
  AND RECORD_CONTENT:source.ts_ms::NUMBER
      > DATE_PART(epoch_millisecond, DATEADD(hour, -1, CURRENT_TIMESTAMP()));

-- 4. Recent MERGE task runs (look for FAILED and its ERROR_MESSAGE).
SELECT name, state, scheduled_time, completed_time, error_message
FROM TABLE(SAP_CORE.INFORMATION_SCHEMA.TASK_HISTORY(
       SCHEDULED_TIME_RANGE_START => DATEADD(hour, -1, CURRENT_TIMESTAMP()),
       RESULT_LIMIT => 200))
ORDER BY scheduled_time DESC;

-- 5. Net revenue: compare with the Oracle query at the end of
--    oracle/s4_sd_sample_data.sql.
SELECT SUM(NET_REVENUE_INR) AS net_revenue_inr FROM SAP_CORE.SD.V_NET_REVENUE_DAILY;

-- 6. Follow one order through the pipeline (the cancelled-and-rebilled one).
SELECT "VBELN", "AUART", "NETWR", "GBSTK", CDC_OP, CDC_SCN, CDC_SOURCE_TS, CDC_LOADED_AT
FROM SAP_CORE.SD.V_VBAK
WHERE "VBELN" = '0000010006';
